function reportDonut(title,total,subtitle,items,format=value=>fmt(value)){let colors=['#07873f','#8fbd62','#f0b83f','#43a0c2','#3f8453','#bad474','#efce74','#6eb49b'],prepared=items.map((item,index)=>({...item,color:colors[index%colors.length]})),sum=prepared.reduce((s,item)=>s+item.value,0),at=0,gradient=sum?prepared.filter(item=>item.value>0).map(item=>{let share=item.value/sum*100,gap=Math.min(1.2,share/4),begin=at+gap/2,end=at+share-gap/2;at+=share;return item.color+' '+begin+'% '+end+'%'}).join(','):'#dfe9e1 0 100%',top=prepared.slice().sort((a,b)=>b.value-a.value).slice(0,6),centerTotal=sum,centerSubtitle=title==='Cropwise Farmers'?'farmer-crop entries':subtitle;return `<article class="glance-card" aria-label="${esc(title)}"><div class="glance-title"><div><span class="glance-overline">LIVE BREAKDOWN</span><h2>${esc(title)}</h2></div><span class="glance-menu" aria-hidden="true">•••</span></div><div class="glance-donut-wrap"><div class="glance-donut" style="background:conic-gradient(${gradient})"><div><strong>${format(centerTotal)}</strong><small>${esc(centerSubtitle)}</small></div></div></div><div class="glance-legend">${top.length?top.map(item=>{let share=sum?Math.round(item.value/sum*100):0;return`<div><i style="background:${item.color}"></i><span>${esc(item.name)}</span><b>${format(item.value)}</b><small>${share}%</small></div>`}).join(''):'<p>No linked data yet.</p>'}</div></article>`}
function reportPage(u){let list=records(u.id),all=records(u.id,false),scopeStats=stats(u.id),totalArea=list.reduce((s,c)=>s+c.area*(c.area_unit==='hectare'?2.47105381:1),0),totalInput=list.reduce((s,c)=>s+c.inputs.reduce((a,i)=>a+i.amount,0),0),totalOutput=list.filter(c=>c.output!==null).reduce((s,c)=>s+c.output/(c.output_unit==='kg'?100:1),0),groups=new Map();for(let c of list){let g=groups.get(c.crop)||{crop:c.crop,records:0,farmers:new Set(),area:0,input:0,output:0};g.records++;g.farmers.add(c.farmer_id);g.area+=c.area*(c.area_unit==='hectare'?2.47105381:1);g.input+=c.inputs.reduce((a,i)=>a+i.amount,0);if(c.output!==null)g.output+=c.output/(c.output_unit==='kg'?100:1);groups.set(c.crop,g)}let rows=[...groups.values()].sort((a,b)=>b.area-a.area),branches=kids(u.id),branchName=u.role<4?types[u.role+1]:'Crop',farmerItems=branches.map(n=>({name:n.name,value:stats(n.id).farmers})),expenseItems=branches.map(n=>({name:n.name,value:stats(n.id).input}));if(u.role===4){farmerItems=rows.map(g=>({name:g.crop,value:g.records}));expenseItems=rows.map(g=>({name:g.crop,value:g.input}))}let cropItems=rows.map(g=>({name:g.crop,value:g.farmers.size})),crops=[...new Set([...state.crops.map(c=>c.crop),...defaultCrops])].filter(Boolean).sort((a,b)=>a.localeCompare(b)),seasons=[...new Set([...state.crops.filter(c=>c.season&&c.year).map(c=>`${c.season} ${c.year}`),...defaultSeasons])].filter(s=>s&&!['Kharif','Rabi','Zaid'].includes(s.trim())),period=new Date().toLocaleDateString('en-IN',{month:'long',year:'numeric'});return `<section class="report-page"><div class="report-head"><div><div class="crumbs"><button data-nav="overview">Overview</button><span>›</span><strong>Reports</strong></div><span class="report-kicker">LIVE NETWORK REPORT</span><h1>Reports and insights</h1><p>Review your permitted network data on screen. Download is optional.</p></div><button class="primary" data-action="export">${icon('download')}Export CSV</button></div><div class="report-filterbar"><div class="report-filterbar-left"><div class="report-filter-item"><span class="report-filter-lbl">Season</span>${customSelect('reportSeason',season,'All seasons',seasons.map(v=>({value:v,label:v})))}</div><div class="report-filter-item"><span class="report-filter-lbl">Crop</span>${customSelect('reportCrop',crop,'All crops',crops.map(v=>({value:v,label:v})))}</div></div><span>${list.length} crop records in this view</span></div><div class="glance-heading"><h2>${u.role===4?'My farm':'Community'} at a glance</h2><span>▣ ${period}</span></div><div class="glance-grid">${u.role===4?reportDonut('My crop records',list.length,'records by crop',farmerItems)+reportDonut('Cultivated area',totalArea,'acres by crop',rows.map(g=>({name:g.crop,value:g.area})))+reportDonut('Total Expense',totalInput,'expenses by crop',expenseItems,money):reportDonut('Total Farmers',scopeStats.farmers,'farmers connected',farmerItems)+reportDonut('Cropwise Farmers',rows.length,'crop varieties',cropItems)+reportDonut('Total '+branchName+'s Expense',totalInput,'total expenses',expenseItems,money)}</div><div class="report-metrics"><article><small>Farmers represented</small><strong>${fmt(scopeStats.farmers)}</strong><span>Unique farmers in the selected view</span></article><article><small>Cultivated area</small><strong>${fmt(totalArea)} <i>acres</i></strong><span></span></article><article><small>Input expense</small><strong>${money(totalInput)}</strong><span>Sum of itemized crop expenses</span></article><article><small>Harvest output</small><strong>${fmt(totalOutput)} <i>qtl</i></strong><span>Output</span></article></div><article class="report-card report-table-card"><div class="report-card-head"><div><h2>Crop performance breakdown</h2><p>Area, expense and harvest totals by crop.</p></div><span class="report-scope">${types[u.role]} access · ${all.length} available records</span></div><div class="table-wrap"><table><thead><tr><th>Crop</th><th>Farmers</th><th>Records</th><th>Area</th><th>Input expense</th><th>Output</th></tr></thead><tbody>${rows.map(g=>`<tr><td><strong>${esc(g.crop)}</strong></td><td>${g.farmers.size}</td><td>${g.records}</td><td>${fmt(g.area)} acres</td><td>${money(g.input)}</td><td>${fmt(g.output)} qtl</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="report-empty">Add crop records to build this report.</div>':''}</article></section>`}
function profilePage(u){return `<section class="profile-page"><div class="profile-page-head"><div><div class="crumbs"><button data-nav="overview">Overview</button><span>›</span><strong>My profile</strong></div><span class="profile-kicker">ACCOUNT &amp; SECURITY SETTINGS</span><h1>My Profile</h1><p>View your account details and change your password.</p></div><div class="profile-status-pill"><span class="pulse-dot"></span><span>Active ${types[u.role]} Account</span></div></div><div class="profile-page-grid"><aside class="profile-identity-card"><div class="profile-avatar-wrap"><span class="profile-page-avatar">${esc(u.name.slice(0,2).toUpperCase())}</span><span class="profile-verified-badge" title="Verified Account">✓</span></div><h2>${esc(u.name)}</h2><span class="profile-role-tag">${types[u.role]} Workspace</span><p class="profile-tagline">Linked Agricultural Partner</p><div class="profile-info-list"><div class="profile-info-item"><span class="info-label">Referral Code / Alternate Login ID</span><div class="info-code-box"><code>${esc(u.code)}</code></div><small>Use with your password to log in anytime</small></div><div class="profile-info-item"><span class="info-label">Protected Phone ID</span><strong class="info-phone">${esc(u.phone)}</strong></div></div></aside><section class="profile-details-column"><article class="profile-card profile-details-card"><div class="profile-card-head"><div class="head-icon">👤</div><div class="head-text"><h2>Personal &amp; Organization Details</h2><p>Your name is visible across your linked agricultural network.</p></div></div><form id="profilePageForm"><div class="profile-fields"><label>Full name / Organization name *<div class="input-editable-wrap"><input name="name" id="profileNameInput" required minlength="2" maxlength="100" autocomplete="name" value="${esc(u.name)}" readonly aria-readonly="true"><span class="view-mode-tag" id="profileNameTag">Read-only</span></div><small id="profileNameHint">Click "Edit Details" to change your name.</small></label><label>Login mobile number<div class="locked-field-wrap"><input name="phone" readonly aria-readonly="true" inputmode="numeric" value="${esc(u.phone)}"><span class="locked-badge" title="Protected ID">🔒 Protected</span></div><small>Primary login ID. Protected against unauthorized modification.</small></label></div><div id="profilePageError" class="form-error" role="alert"></div><div class="profile-page-actions" id="profileViewActions"><button class="edit-pill-btn" type="button" id="editProfileBtn">Edit name</button></div><div class="profile-page-actions" id="profileEditActions" style="display:none"><button class="secondary" type="button" id="cancelEditProfile">Cancel</button><button class="primary" type="submit">Save name</button></div></form></article><article class="profile-card profile-security-card"><div class="profile-card-head"><div class="head-icon">🛡️</div><div><h2>Change password</h2></div></div><div class="security-action-box"><div class="security-info"><strong>Password security</strong><p>Changing your password signs out other active sessions.</p></div><button class="primary" type="button" data-action="password">Change password ➔</button></div></article></section></div></section>`}
function farmerCharts(){let groups=Object.create(null);for(let c of records(current)){let g=groups[c.crop]??={name:c.crop,records:0,area:0,input:0,output:0};g.records++;g.area+=c.area*(c.area_unit==='hectare'?2.47105381:1);g.input+=c.inputs.reduce((sum,input)=>sum+input.amount,0);if(c.output!==null)g.output+=c.output/(c.output_unit==='kg'?100:1);groups[c.crop]=g}let items=Object.values(groups).sort((a,b)=>b.area-a.area),key=metric==='farmers'?'records':metric,labels={records:'Crop records',area:'Cultivated area in acres',input:'Input expense in rupees',output:'Harvest output in quintals'},vals=items.map(item=>item[key]),max=Math.max(...vals,1),valueFormat=key==='input'?money:fmt,bars=items.map((item,index)=>'<div class="bar-group"><strong>'+valueFormat(vals[index])+'</strong><span class="bar farmer-chart-bar" style="height:'+Math.max(2,vals[index]/max*80)+'%" aria-label="'+esc(item.name)+': '+valueFormat(vals[index])+'"></span></div>').join(''),legend=items.map(item=>'<div><span>'+esc(item.name)+'</span><b>'+fmt(item.records)+' record'+(item.records===1?'':'s')+'</b><progress value="'+item.records+'" max="'+Math.max(...items.map(row=>row.records),1)+'"></progress></div>').join('');return '<section class="charts"><article class="panel"><div class="panel-head"><div><h2>My crop performance</h2><p>'+labels[key]+' · your own crop records</p></div><div class="tabs">'+['farmers','area','input','output'].map(tab=>'<button data-metric="'+tab+'" class="'+(tab===metric?'selected':'')+'">'+(tab==='farmers'?'Records':tab[0].toUpperCase()+tab.slice(1))+'</button>').join('')+'</div></div>'+ (items.length?'<div class="bar-scroll"><div class="plot" style="min-width:'+Math.max(300,items.length*95)+'px">'+bars+'</div><div class="chart-labels" style="min-width:'+Math.max(300,items.length*95)+'px">'+items.map(item=>'<span>'+esc(item.name)+'</span>').join('')+'</div></div>':'<div class="empty">Your crop diary starts here.<br>Add a crop record to see your progress.</div>')+'<div class="chart-foot">'+icon('chart')+' Values follow your crop and season filters.</div></article><article class="panel"><h2>My crop diary</h2><p>Crop records by crop</p>'+ (items.length?'<div class="crop-breakdown">'+legend+'</div>':'<div class="empty">No crop records yet.<br>Add your first crop record to begin.</div>')+'<div class="insight">Each crop and season stays as a separate farm record.</div></article></section>'}
function charts(r){if(node(current)?.role===4)return farmerCharts();let vals=r.map(n=>stats(n.id)[metric]),max=Math.max(...vals.filter(v=>v!==null),1),groups=Object.create(null);for(let c of records(current)){groups[c.crop]??=new Set();groups[c.crop].add(c.farmer_id)}let grouped=Object.entries(groups);return `<section class="charts"><article class="panel"><div class="panel-head"><div><h2>${types[node(current).role+1]} performance</h2><p>${metric==='input'?'Expense in rupees':metric==='area'?'Cultivated area in acres':metric==='output'?'Harvest in quintals':'Unique farmers'} · click a bar for details</p></div><div class="tabs">${['farmers','area','input','output'].map(k=>`<button data-metric="${k}" class="${k===metric?'selected':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div></div>${metric==='output'&&!crop?'<div class="empty">Select a crop above to compare harvest output.</div>':r.length?`<div class="bar-scroll"><div class="plot" style="min-width:${Math.max(300,r.length*95)}px">${r.map((n,i)=>`<div class="bar-group"><strong>${metric==='input'?money(vals[i]):fmt(vals[i])}</strong><button class="bar" style="height:${Math.max(2,vals[i]/max*80)}%" data-go="${n.id}" aria-label="Open ${esc(n.name)}: ${fmt(vals[i])}"></button></div>`).join('')}</div><div class="chart-labels" style="min-width:${Math.max(300,r.length*95)}px">${r.map(n=>`<span>${esc(n.name)}</span>`).join('')}</div></div>`:'<div class="empty">Your network starts here.<br>Add your first member to see their progress.</div>'}<div class="chart-foot">${icon('chart')} Values follow your crop and season filters.</div></article><article class="panel"><h2>What’s growing?</h2><p>Farmers by crop</p>${grouped.length?`<div class="crop-breakdown">${grouped.map(([c,ids])=>`<div><span>${esc(c)}</span><b>${ids.size} farmers</b><progress value="${ids.size}" max="${Math.max(...grouped.map(([,s])=>s.size))}"></progress></div>`).join('')}</div>`:'<div class="empty">No crop records yet.<br>Farmer entries will appear here.</div>'}<div class="insight">A farmer can grow multiple crops. Each crop counts its own unique farmers.</div></article></section>`}
function memberTable(r){let manage=node(current).id===state.user.id;return `<div class="table-wrap"><table><thead><tr><th>Name / referral code</th><th>Farmers</th><th>Area</th><th>Input expense</th><th>Status</th><th>Actions</th></tr></thead><tbody>${r.map(n=>{let s=stats(n.id);return`<tr><td><div class="name-cell"><span class="initial">${esc(n.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(n.name)}</strong><small>${esc(n.code)}</small></div></div></td><td>${s.farmers}</td><td>${fmt(s.area)} acres</td><td>${money(s.input)}</td><td><span class="badge ${!n.active?'inactive':''}">${!n.active?'Inactive':n.activated?'Active':'Pending activation'}</span></td><td><div class="row-actions"><button class="view-btn" data-go="${n.id}">View →</button>${manage?`<button class="view-btn" data-manage="${n.id}">Manage</button><button class="delete-btn" data-delete="${n.id}">Delete</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>${!r.length?'<div class="empty">No matching members. Add a member or change your search.</div>':''}<div class="table-footer"><span>${r.length} members</span><span>Connected to ${esc(node(current).name)}</span></div>`}
function cropTable(n){let list=records(n.id);return `<div class="table-wrap"><table><thead><tr><th>Crop / season</th><th>Area</th><th>Input expense</th><th>Output</th><th>Actions</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.crop)}</strong><br><small>${esc(c.season)} ${c.year}</small></td><td>${fmt(c.area)} ${c.area_unit}</td><td>${money(c.inputs.reduce((s,i)=>s+i.amount,0))}</td><td>${c.output===null?'Awaiting harvest':fmt(c.output)+' '+c.output_unit}</td><td><button class="view-btn" data-record="${c.id}">${canEditFarmer(n)?'Edit / details':'Details'}</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">No crop records for these filters. Add a crop record to begin.</div>':''}`}
function bind(){bindCustomSelects();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{current=b.dataset.go;query='';render()});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$('#addCropRecord')?.addEventListener('click',event=>{event.preventDefault();openCropRecordForm()});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>cropForm(b.dataset.record));document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>manage(b.dataset.manage));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteMember(b.dataset.delete));$('#crop')?.addEventListener('change',e=>{crop=e.target.value;render()});$('#season')?.addEventListener('change',e=>{season=e.target.value;render()});$('#search')?.addEventListener('input',e=>{query=e.target.value;$('#table').innerHTML=memberTable(kids(current).filter(n=>(n.name+' '+n.code).toLowerCase().includes(query.toLowerCase())));document.querySelectorAll('#table [data-go]').forEach(b=>b.onclick=()=>{current=b.dataset.go;query='';render()});document.querySelectorAll('#table [data-manage]').forEach(b=>b.onclick=()=>manage(b.dataset.manage));document.querySelectorAll('#table [data-delete]').forEach(b=>b.onclick=()=>deleteMember(b.dataset.delete))});$('#reportCrop')?.addEventListener('change',e=>{crop=e.target.value;render()});$('#reportSeason')?.addEventListener('change',e=>{season=e.target.value;render()});$('#profilePageForm')?.addEventListener('submit',async e=>{e.preventDefault();let button=e.target.querySelector('[type=submit]');button.disabled=true;$('#profilePageError').textContent='';try{await api('profile','PATCH',{...Object.fromEntries(new FormData(e.target)),version:state.user.version});await refresh();view='profile';render();toast('Profile updated successfully.')}catch(err){$('#profilePageError').textContent=err.message;button.disabled=false}});let pInput=$('#profileNameInput'),pView=$('#profileViewActions'),pEdit=$('#profileEditActions'),pTag=$('#profileNameTag'),pHint=$('#profileNameHint'),pBtn=$('#editProfileBtn');const setProfileEditing=on=>{if(!pInput)return;pInput.readOnly=!on;pInput.classList.toggle('is-editing',on);if(pTag)pTag.style.display=on?'none':'';if(pHint)pHint.textContent=on?'Enter your updated name and click "Save Changes".':'Click "Edit Details" to change your name.';if(pView)pView.style.display=on?'none':'flex';if(pEdit)pEdit.style.display=on?'flex':'none';if(pBtn)pBtn.style.display=on?'none':'inline-flex';if(on){pInput.focus();pInput.select()}else{pInput.value=state.user.name;$('#profilePageError').textContent=''}};$('#editProfileBtn')?.addEventListener('click',()=>setProfileEditing(true));$('#editProfileBtnBottom')?.addEventListener('click',()=>setProfileEditing(true));$('#cancelEditProfile')?.addEventListener('click',()=>setProfileEditing(false));$('#codeLookup')?.addEventListener('submit',e=>{e.preventDefault();let code=$('#memberCode').value.trim().toUpperCase(),childRole=state.user.role+1,match=kids(state.user.id).find(n=>n.role===childRole&&n.code.toUpperCase()===code);if(!match){$('#memberCodeError').textContent=`This ${types[childRole]} code is not linked to your ${types[state.user.role]}. Check the code and try again.`;return}current=match.id;query='';crop='';season='';view='overview';render()})}
async function action(key){try{if(key==='logout'){await api('logout','POST',{});state=null;current=null;login();return}if(key==='refresh'){await refresh();toast('Latest records loaded.');return}if(key==='export'){exportData();return}if(key==='add')return addMember();if(key==='crop')return cropForm();if(key==='profile'){view='profile';current=state.user.id;render();return}if(key==='password')return passwordForm()}catch(e){message(e)}}
function dialog(title,subtitle,fields,submit,saveLabel='Save changes'){let d=$('#dialog');if(!d){d=document.createElement('dialog');d.id='dialog';document.body.append(d)};d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(subtitle)}</p><form id="entry"><div class="form-grid">${fields}</div><div class="form-error" id="formerror" role="alert"></div><div class="actions"><button class="secondary" type="button" id="cancel">Cancel</button>${submit?`<button class="primary" type="submit">${saveLabel}</button>`:''}</div></form>`;if(!d.open){if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','')}$('#cancel').onclick=()=>d.close();$('#entry').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('[type=submit]');b.disabled=true;$('#formerror').textContent='';try{let result=await submit(Object.fromEntries(new FormData(e.target)));d.close();await refresh();if(result?.activationToken)showInvitation(result);else toast('Saved to database. Linked reports updated.')}catch(err){$('#formerror').textContent=err.message;b.disabled=false}};return d}
function addMember(){dialog('Add '+types[state.user.role+1],'This account will be linked to '+state.user.name+'.','<label>Name / organization *<input name="name" required minlength="2" maxlength="100"><small>The same name may be used with a different mobile number.</small></label><label>Mobile number *<input name="phone" required inputmode="numeric" pattern="[0-9]{10}" maxlength="10"><small>Every account must have a unique 10-digit login mobile number.</small></label>',data=>api('members','POST',data),'Create account')}
function showInvitation(result){let url=location.origin+'/#activate='+result.activationToken+'&code='+encodeURIComponent(result.member.code);let d=$('#dialog');d.innerHTML=`<h2>Account ready to activate</h2><p>${esc(result.member.name)} · ${esc(result.member.code)}</p><div class="invitation"><label>Private activation link<div class="copy-input-row"><input id="inviteurl" readonly value="${esc(url)}"><button type="button" class="copy-field-btn" id="copyUrlBtn">📋 Copy Link</button></div></label><label>Referral code<div class="copy-input-row"><input id="invitecode" readonly value="${esc(result.member.code)}"><button type="button" class="copy-field-btn" id="copyCodeBtn">📋 Copy Code</button></div></label><p>Valid for 48 hours and one use. Share privately with this member. They will set their own password, then may use this referral code or their mobile number to log in.</p></div><div class="actions"><button class="primary" id="doneinvite">Done</button></div>`;if(!d.open){if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','')}$('#copyUrlBtn').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Activation link copied to clipboard.');let b=$('#copyUrlBtn');if(b){b.textContent='✓ Copied!';setTimeout(()=>b.textContent='📋 Copy Link',2000)}}catch{$('#inviteurl').select();toast('Select and copy the activation link.')}};$('#copyCodeBtn').onclick=async()=>{try{await navigator.clipboard.writeText(result.member.code);toast('Referral code copied to clipboard.');let b=$('#copyCodeBtn');if(b){b.textContent='✓ Copied!';setTimeout(()=>b.textContent='📋 Copy Code',2000)}}catch{$('#invitecode').select();toast('Select and copy the referral code.')}};$('#doneinvite').onclick=()=>d.close()}
async function deleteMember(id){let n=node(id);if(!n)return;let branch=descendants(id),farmers=branch.filter(x=>x.role===4).length;if(!confirm(`Permanently delete ${n.name} and its complete linked branch?\n\n${branch.length} account(s), ${farmers} farmer(s), crop records and login access will be removed. This cannot be undone.`))return;try{let result=await api(`members/${id}`,'DELETE',{});query='';crop='';season='';current=state.user.id;await refresh();toast(`${result.deleted.account} and its linked data were deleted.`)}catch(e){message(e)}}
function manage(id){let n=node(id),d=$('#dialog');d.innerHTML=`<h2>${esc(n.name)}</h2><p>${esc(n.code)} · ${esc(n.phone)}</p><div class="manage-options"><p>Issuing a new activation link signs this account out and replaces its password access until it activates again.</p><button class="secondary" id="reinvite">Issue new activation link</button><p>Deactivating blocks this account and its entire branch from signing in. Historical records stay in reports.</p><button class="secondary" id="toggleactive">${n.active?'Deactivate account':'Reactivate account'}</button></div><div id="formerror" class="form-error" role="alert"></div><button class="primary" id="closemanage">Done</button>`;d.showModal();$('#closemanage').onclick=()=>d.close();$('#reinvite').onclick=async e=>{if(!confirm('Replace this account’s activation and sign it out?'))return;e.target.disabled=true;try{let result=await api(`members/${id}/invite`,'POST',{});await refresh();showInvitation(result)}catch(err){$('#formerror').textContent=err.message;e.target.disabled=false}};$('#toggleactive').onclick=async e=>{if(n.active&&!confirm('Deactivate this account and block logins for its branch?'))return;e.target.disabled=true;try{await api(`members/${id}/status`,'POST',{active:!n.active});d.close();await refresh();toast('Account status updated.')}catch(err){$('#formerror').textContent=err.message;e.target.disabled=false}}}
function profileForm(){let u=state.user,d=dialog('My profile','Manage your account name and login mobile number.',`<div class="profile-summary wide"><span class="profile-avatar">${esc(u.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(u.name)}</strong><span>${types[u.role]} · ${esc(u.code)}</span></div><i>Active account</i></div><label>Name *<input name="name" required minlength="2" maxlength="100" autocomplete="name" value="${esc(u.name)}"><small>Use your full name or organization name.</small></label><label>Mobile number *<input name="phone" required inputmode="numeric" pattern="[0-9]{10}" maxlength="10" autocomplete="username" value="${esc(u.phone)}"><small>This number is your login ID.</small></label><label class="wide">Confirm with current password *<div class="profile-password"><input name="password" required type="password" autocomplete="current-password" placeholder="Enter your current password"><button type="button" id="toggleProfilePassword" aria-label="Show password">Show</button></div><small>Your password is required before account details can change.</small></label>`,data=>api('profile','PATCH',{...data,version:u.version}));d.classList.add('profile-dialog');d.addEventListener('close',()=>d.classList.remove('profile-dialog'),{once:true});$('#toggleProfilePassword').onclick=e=>{let input=e.currentTarget.previousElementSibling,show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password')}}
function passwordForm(){let d=dialog('Change password','Use at least 6 characters. Other signed-in sessions will be signed out.',`<label class="wide">Current password${passwordBox('current','current-password','Enter current password')}</label><label>New password${passwordBox('password','new-password','At least 6 characters',6)}</label><label>Confirm new password${passwordBox('confirm','new-password','Re-enter new password',6)}</label>`,async data=>{if(data.password!==data.confirm)throw Error('Passwords do not match.');let r=await api('password','POST',data);state.csrf=r.csrf});bindPasswordToggles(d)}
function inputRow(i={}){return `<div class="input-row"><label>Item *<input data-field="item" required maxlength="80" value="${esc(i.item)}" placeholder="Seeds, fertilizer…"></label><label>Quantity<input data-field="quantity" type="number" min="0" step="0.01" value="${i.quantity??''}"></label><label>Unit<input data-field="unit" maxlength="20" value="${esc(i.unit)}" placeholder="kg / bag"></label><label>Expense (₹) *<input data-field="amount" type="number" required min="0" step="0.01" value="${i.amount??''}"></label><label>Date *<input data-field="date" type="date" required value="${esc(i.date||today())}"></label><button type="button" class="remove-input" aria-label="Remove input item">×</button></div>`}
function cropForm(id){let c=state.crops.find(c=>c.id===id),n=node(c?.farmer_id||current),editable=canEditFarmer(n);if(!editable){dialog(c.crop+' · '+c.season+' '+c.year,'Crop record details',`<div class="wide"><p>Area: ${fmt(c.area)} ${c.area_unit}</p><p>Output: ${c.output===null?'Awaiting harvest':fmt(c.output)+' '+c.output_unit}</p><h3>Inputs</h3>${c.inputs.length?c.inputs.map(i=>`<p>${esc(i.item)} · ${i.quantity===null?'':fmt(i.quantity)+' '+esc(i.unit)+' · '}${money(i.amount)} · ${esc(i.date)}</p>`).join(''):'<p>No expenses recorded.</p>'}<p>Updated ${new Date(c.updated_at).toLocaleString()}</p></div>`,null);return}c??={crop:'',season:'Rabi',year:new Date().getFullYear(),record_date:today(),area:'',area_unit:'acre',output:null,output_unit:'quintal',inputs:[]};let fields=`<label>Crop name *<input name="crop" list="cropnames" required minlength="2" maxlength="60" value="${esc(c.crop)}"><datalist id="cropnames">${defaultCrops.map(n=>'<option>'+n+'</option>').join('')}</datalist></label><label>Season *<select name="season">${['Rabi','Kharif','Zaid'].map(s=>`<option ${s===c.season?'selected':''}>${s}</option>`).join('')}</select></label><label class="crop-date-field">Crop date *<input name="record_date" required type="date" value="${esc(c.record_date||(String(c.year)+'-01-01'))}"><small>Used to organize your crop record by year.</small></label><div class="measure-field"><label>Area *<input name="area" type="number" required min="0.01" max="10000000000" step="0.01" value="${c.area}"></label><label class="measure-unit">Area unit<select name="area_unit"><option ${c.area_unit==='acre'?'selected':''}>acre</option><option ${c.area_unit==='hectare'?'selected':''}>hectare</option></select></label></div><div class="measure-field"><label>Harvest output<input name="output" type="number" min="0" max="10000000000" step="0.01" value="${c.output??''}" placeholder="Leave blank until harvested"></label><label class="measure-unit">Output unit<select name="output_unit"><option ${c.output_unit==='quintal'?'selected':''}>quintal</option><option ${c.output_unit==='kg'?'selected':''}>kg</option></select></label></div><div class="wide"><h3>Input expenses</h3><p>Record individual items. Total expense is calculated automatically.</p><div id="inputrows">${c.inputs.map(inputRow).join('')}</div><button class="secondary" id="addinput" type="button">+ Add input item</button><p id="inputtotal" class="input-total"></p></div>`;let d=dialog(id?'Edit crop record':'Add crop record','Farmer: '+n.name+' · Keep each crop and season as a separate record.',fields,async data=>{let inputs=[...document.querySelectorAll('.input-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));await api('crops'+(id?'/'+id:''),id?'PATCH':'POST',{...data,year:Number(data.record_date.slice(0,4)),farmer_id:n.id,version:c.version,inputs})});d.classList.add('crop-dialog');d.addEventListener('close',()=>d.classList.remove('crop-dialog'),{once:true});const total=()=>{$('#inputtotal').textContent='Total input expense: '+money([...document.querySelectorAll('[data-field=amount]')].reduce((s,el)=>s+(Number(el.value)||0),0))};const bindRows=()=>{document.querySelectorAll('.remove-input').forEach(b=>b.onclick=()=>{b.closest('.input-row').remove();total()});document.querySelectorAll('[data-field=amount]').forEach(el=>el.oninput=total);total()};$('#addinput').onclick=()=>{$('#inputrows').insertAdjacentHTML('beforeend',inputRow());bindRows()};bindRows()}
function exportData(){const safe=s=>'"'+String(s??'').replace(/^[\s]*[=+@-]/,"'").replace(/"/g,'""')+'"';let rows=[['Farmer','Mobile','Code','Crop','Season','Year','Area','Area unit','Input INR','Output','Output unit'],...records(current).map(c=>{let n=node(c.farmer_id);return[n.name,n.phone,n.code,c.crop,c.season,c.year,c.area,c.area_unit,c.inputs.reduce((s,i)=>s+i.amount,0),c.output,c.output_unit]})];let blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='agridoot-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report exported for the selected network and filters.')}
const skeletonScreen=()=>`<div class="startup-loader" aria-busy="true" aria-label="Loading Agridoot"><div class="startup-loader-card">${brandLogo()}<span class="startup-loader-spinner" aria-hidden="true"></span><p>Loading secure portal</p></div></div>`;
async function boot(){try{let status=await api('status');if(status.setupRequired)return login('setup');if(activation)return login('activate');try{await refresh()}catch(e){if(e.status===401)login();else throw e}}catch(e){$('#app').innerHTML=`<div class="startup-error"><h1>Unable to connect</h1><p>${esc(e.message)}</p><p>Start the Agridoot server, then refresh this page.</p><button class="primary" id="retry">Retry</button></div>`;$('#retry').onclick=()=>{if($('#app'))$('#app').innerHTML=skeletonScreen();boot()}}}
setInterval(async()=>{if(state&&!document.hidden&&!$('#dialog').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){try{await refresh(true,true)}catch(e){let s=$('#sync');if(s)s.textContent='Connection interrupted · retrying'}}},20000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state&&!$('#dialog').open)refresh().catch(message)});
function syncHarvestCard(){let card=$('.stat-4');if(!card||!state)return;let s=stats(current),signature=[current,crop,season,s.output,s.harvested,s.missing].join('|');if(card.dataset.harvestSignature===signature)return;card.dataset.harvestSignature=signature;let label=card.querySelector('.stat-top'),value=card.querySelector('strong'),detail=card.querySelector('small');if(label?.firstChild)label.firstChild.nodeValue=(crop?crop+' output':'Harvest output');if(value)value.innerHTML=fmt(s.output)+' <small>qtl</small>';if(detail)detail.textContent=s.harvested?`${s.harvested} harvested record${s.harvested===1?'':'s'}${s.missing?' · '+s.missing+' awaiting harvest':''}`:'No harvest output recorded yet'}
new MutationObserver(()=>setTimeout(syncHarvestCard,0)).observe($('#app'),{childList:true,subtree:true});
// The crop CTA is rendered dynamically. Handle it at document level so it still
// opens its form after any dashboard refresh or re-render.
function openCropRecordForm(){
  if(!state)return;
  try{cropForm()}catch(error){message(error)}
}
document.addEventListener('click',event=>{let button=event.target.closest('[data-action="crop"]');if(!button||!state||!current)return;event.preventDefault();event.stopImmediatePropagation();openCropRecordForm()},true);
function installMobileDrawer(){
  let topbar=$('.topbar'),tools=$('.mobile-tools');
  if(!topbar||!tools||$('#mobileNavToggle'))return;
  tools.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav===view));
  tools.querySelector('[data-action="profile"]')?.classList.toggle('active',view==='profile');
  let toggle=document.createElement('button'),scrim=$('#mobileNavScrim');
  toggle.id='mobileNavToggle';
  toggle.type='button';
  toggle.className='mobile-nav-toggle';
  toggle.setAttribute('aria-label','Open navigation menu');
  toggle.setAttribute('aria-expanded','false');
  toggle.innerHTML='<i></i><i></i><i></i>';
  topbar.querySelector('.header-actions')?.before(toggle);
  if(!scrim){scrim=document.createElement('button');scrim.id='mobileNavScrim';scrim.type='button';scrim.tabIndex=-1;scrim.setAttribute('aria-label','Close navigation menu');document.body.append(scrim)}
  const close=()=>{tools.classList.remove('is-open');scrim.classList.remove('is-visible');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation menu')};
  toggle.onclick=()=>{let open=!tools.classList.contains('is-open');tools.classList.toggle('is-open',open);scrim.classList.toggle('is-visible',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu')};
  scrim.onclick=close;
  tools.addEventListener('click',close,true);
}
new MutationObserver(()=>setTimeout(installMobileDrawer,0)).observe($('#app'),{childList:true,subtree:true});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('.mobile-tools')?.classList.contains('is-open'))$('#mobileNavToggle')?.click()});
boot();

